$ErrorActionPreference='Stop'
Write-Host 'QUEST_DUNGEON291: VIENS KOPIGS DATU KOMPLEKTS; TIKAI LASISANA'
Write-Host 'NAV SQL IZMAINU, PARSTARTESANAS VAI INSTALACIJAS'
if($env:OS -ne 'Windows_NT' -or ![Environment]::Is64BitProcess){throw 'USE_WINDOWS_X64_POWERSHELL'}
$folder=Join-Path $env:USERPROFILE ('Downloads\QuestDungeon291-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6))
[void](New-Item -ItemType Directory -Path $folder)
$clientFolder=Join-Path $folder 'ClientDecoded'
[void](New-Item -ItemType Directory -Path $clientFolder)
$report=[ordered]@{Status='COLLECTING';ProcessWrites=$false;SQLChanges=$false;ServiceActions=$false;Client=@();ClientFailure=$null;NativeFailure=$null}
try {
    $code=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    Write-Host 'NOLASU VISAS SERVERA SCP DEFINICIJAS; IEVADI SSH PAROLI'
    $remote=@($code | & ssh.exe root@192.168.56.101 python3 -)
    if($LASTEXITCODE -ne 0){throw 'NATIVE_DATA_READ_FAILED'}
    $native=($remote -join "`n") | ConvertFrom-Json
    $bytes=[Convert]::FromBase64String($native.zip_b64)
    $sha=[Security.Cryptography.SHA256]::Create()
    try { $hash=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally {$sha.Dispose()}
    if($hash -ne $native.sha256 -or $bytes.Length -ne $native.bytes){throw 'NATIVE_ZIP_HASH_OR_SIZE_DIFFERS'}
    [IO.File]::WriteAllBytes((Join-Path $folder 'NativeData.zip'),$bytes)
    $report.NativeStatus=$native.status;$report.NativeFiles=$native.files;$report.NativeZIP_SHA256=$hash
    Write-Host ('SERVERA_FAILI='+$native.files)
} catch { $report.NativeFailure=$_.Exception.GetBaseException().Message;Write-Host ('NATIVE_KLUDA='+$report.NativeFailure) }
try {
    $games=@(Get-Process -Name CabalMain -ErrorAction SilentlyContinue | Where-Object { $_.Path -eq 'F:\CABAL_291_TEST\Bin\x64\CabalMain.exe' })
    if($games.Count -ne 1){throw 'ATVER F:\CABAL_291_TEST\Start.bat LIDZ LOGIN LOGAM; VAJADZIGS VIENS KLIENTS'}
    if((Get-FileHash -LiteralPath $games[0].Path -Algorithm SHA256).Hash -ne '52e7956d4781fea1f0369cac8ab1eac4c3ddec2d1977c6557be53ec2b79885d9'){throw 'CLIENT_BINARY_PROFILE_DIFFERS'}
    $source=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
    if(!('Client291QuestDungeonRead' -as [type])){Add-Type -TypeDefinition $source -Language CSharp}
    $handle=[Client291QuestDungeonRead]::OpenReadOnly($games[0].Id)
    try {
        [Client291QuestDungeonRead]::CheckNativeCacheContract($handle)
        $names=@{1='data';2='Mob';3='script';5='cont';7='cont2';15='extra_obj';18='smob';21='maze';22='item';23='item2';24='item3';25='item4';28='mapinfo';29='quest';76='dungeon_timelimit';83='GuildDungeon';93='RandomWarp';110='ChallengeDungeon';128='dungeonboost';130='warp'}
        foreach($index in ($names.Keys | Sort-Object)){
            try {
                $row=[Client291QuestDungeonRead]::ReadDefinition($handle,[int]$index,$names[$index])
                if($row.Data){[IO.File]::WriteAllBytes((Join-Path $clientFolder ($row.Name+'.xml')),$row.Data)}
                $report.Client+=@([ordered]@{Name=$row.Name;Index=$row.Index;Status=$row.Status;Root=$row.Root;Bytes=$row.Bytes;SHA256=$row.SHA256})
            } catch { $report.Client+=@([ordered]@{Name=$names[$index];Index=$index;Status='READ_FAILED';Error=$_.Exception.GetBaseException().Message}) }
        }
    } finally { [Client291QuestDungeonRead]::Close($handle) }
} catch { $report.ClientFailure=$_.Exception.GetBaseException().Message;Write-Host ('CLIENT_KLUDA='+$report.ClientFailure) }
$good=@($report.Client | Where-Object {$_.Status -eq 'STABLE_ORIGINAL_DECODED_GAME_DEFINITION'})
$report.ClientFiles=$good.Count
$report.Status=if(!$report.NativeFailure -and !$report.ClientFailure -and $report.NativeStatus -eq 'READ_ONLY_COMPLETE' -and $good.Count -eq 20){'READ_ONLY_COMPLETE'}else{'READ_ONLY_PARTIAL'}
$report | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $folder 'Collection-Report.json') -Encoding UTF8
$zip=$folder+'.zip'
Compress-Archive -LiteralPath @(Get-ChildItem -LiteralPath $folder | Select-Object -ExpandProperty FullName) -DestinationPath $zip -CompressionLevel Optimal
Write-Host ('STATUS='+$report.Status+'; CLIENT_FILES='+$good.Count)
Write-Host ('ZIP='+$zip)
Write-Host 'ATSUTI SO ZIP ARI JA STATUSS IR PARTIAL; SAGLABATIE DATI NETIEK ATMESTI'
